function cx(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(' '); }
function fmtDate(value?: string | null) { return value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : 'Not yet'; }
function fmtTime(value?: string | null) { return value ? new Date(value).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : '—'; }
function getProjectId(pathname: string) {
  const projectId = pathname.match(/\/projects\/([^/]+)/)?.[1] ?? '';
  return projectId === 'new' ? '' : projectId;
}

function Logo({ dark = false }: { dark?: boolean }) {
  return <Link href="/" data-testid="link-logo" className="flex items-center gap-2.5 group">
    <span className={cx('grid h-8 w-8 place-items-center rounded-[10px] transition-transform group-hover:rotate-6', dark ? 'bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]')}><span className="font-display text-sm font-bold">S</span></span>
    <span className={cx('font-display text-[17px] font-semibold tracking-[-.04em]', dark ? 'text-[hsl(var(--primary-foreground))]' : 'text-foreground')}>SEOlytic</span>
  </Link>;
}

function ScoreRing({ score, size = 132, label = 'site health' }: { score?: number | null; size?: number; label?: string }) {
  const value = Math.round(score ?? 0);
  const radius = 46; const circumference = 2 * Math.PI * radius;
  return <div className="relative shrink-0" style={{ width: size, height: size }}>
    <svg width={size} height={size} viewBox="0 0 112 112" className="-rotate-90">
      <circle cx="56" cy="56" r={radius} fill="none" stroke="hsl(var(--muted))" strokeWidth="8" />
      <circle cx="56" cy="56" r={radius} fill="none" stroke={value >= 80 ? 'hsl(var(--primary))' : value >= 60 ? 'hsl(var(--accent))' : 'hsl(var(--destructive))'} strokeWidth="8" strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={circumference - circumference * value / 100} className="transition-all duration-700" />
    </svg>
    <div className="absolute inset-0 grid place-items-center text-center"><div><div className="font-display text-3xl font-semibold tracking-[-.07em]">{value}</div><div className="font-mono-ui text-[9px] uppercase tracking-[.12em] text-muted-foreground">{label}</div></div></div>
  </div>;
}

function Sparkline({ points = [] }: { points?: Array<{ score: number }> }) {
  const values = points.length ? points.map(p => p.score) : [62, 64, 63, 69, 71, 76, 78];
  const min = Math.min(...values) - 4; const max = Math.max(...values) + 4;
  const path = values.map((value, index) => `${index ? 'L' : 'M'} ${(index / Math.max(values.length - 1, 1)) * 100} ${100 - ((value - min) / (max - min)) * 100}`).join(' ');
  return <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-16 w-full overflow-visible"><path d={path} fill="none" stroke="hsl(var(--primary))" strokeWidth="2.5" vectorEffect="non-scaling-stroke" strokeLinecap="round" /></svg>;
}

function StatusBadge({ status }: { status: string }) {
  const styles: Record<string, string> = { active: 'bg-primary/10 text-primary', crawling: 'bg-accent/20 text-amber-800', paused: 'bg-muted text-muted-foreground', error: 'bg-destructive/10 text-destructive', completed: 'bg-primary/10 text-primary', queued: 'bg-secondary text-secondary-foreground', failed: 'bg-destructive/10 text-destructive' };
  return <span data-testid={`status-${status}`} className={cx('inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 font-mono-ui text-[10px] uppercase tracking-[.08em]', styles[status] ?? styles.paused)}><span className={cx('h-1.5 w-1.5 rounded-full bg-current', status === 'crawling' && 'pulse-dot')} />{status}</span>;
}

function Skeleton({ className }: { className?: string }) { return <div className={cx('animate-pulse rounded-lg bg-muted', className)} />; }
function LoadingBlock({ label = 'Loading evidence' }: { label?: string }) { return <div className="space-y-4"><Skeleton className="h-7 w-48" /><Skeleton className="h-24 w-full" /><div className="grid gap-4 sm:grid-cols-3"><Skeleton className="h-28" /><Skeleton className="h-28" /><Skeleton className="h-28" /></div><p className="font-mono-ui text-[10px] uppercase tracking-[.12em] text-muted-foreground">{label}</p></div>; }
function ErrorState({ onRetry }: { onRetry: () => void }) { return <div className="rounded-xl border border-destructive/20 bg-destructive/5 p-8 text-center"><XCircle className="mx-auto mb-3 text-destructive" size={26} /><h3 className="font-display text-lg font-semibold">The audit data did not load</h3><p className="mt-1 text-sm text-muted-foreground">Try again, or check the project connection.</p><button onClick={onRetry} data-testid="button-retry" className="mt-5 inline-flex items-center gap-2 rounded-lg bg-foreground px-4 py-2 text-sm font-semibold text-background"><RefreshCw size={14} /> Retry</button></div>; }
function EmptyState({ icon: Icon = FileCode2, title, body, action }: { icon?: typeof FileCode2; title: string; body: string; action?: React.ReactNode }) { return <div className="rounded-xl border border-dashed border-border bg-card/40 p-12 text-center"><Icon className="mx-auto mb-4 text-primary/70" size={28} /><h3 className="font-display text-lg font-semibold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div>; }

