function AppSidebar({ project }: { project?: Project }) {
  const [location, setLocation] = useLocation(); const [open, setOpen] = useState(false);
  const projectId = project?.id ?? getProjectId(location);
  const links = projectId ? [{ href: `/projects/${projectId}`, label: 'Overview', icon: LayoutDashboard }, { href: `/projects/${projectId}/pages`, label: 'Pages', icon: FileCode2 }, { href: `/projects/${projectId}/issues`, label: 'Issues', icon: TriangleAlert }, { href: `/projects/${projectId}/crawls`, label: 'Crawls', icon: History }, { href: `/projects/${projectId}/assistant`, label: 'AI assistant', icon: Bot }] : [];
  return <><button onClick={() => setOpen(!open)} data-testid="button-mobile-menu" className="fixed left-4 top-4 z-40 rounded-lg border border-border bg-card p-2 lg:hidden"><Menu size={18} /></button><aside className={cx('fixed inset-y-0 left-0 z-30 flex w-[252px] flex-col border-r border-sidebar-border bg-sidebar px-4 py-5 transition-transform lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}><div className="px-2"><Logo /></div><div className="mt-10"><p className="px-3 font-mono-ui text-[9px] uppercase tracking-[.16em] text-muted-foreground">Workspace</p><Link href="/app" onClick={() => setOpen(false)} data-testid="link-workspace" className={cx('mt-2 flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors', location === '/app' ? 'bg-primary/10 font-semibold text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><BarChart3 size={16} /> All projects</Link></div>{projectId && <div className="mt-7"><p className="truncate px-3 font-mono-ui text-[9px] uppercase tracking-[.16em] text-muted-foreground">{project?.name ?? 'Project'}</p><nav className="mt-2 space-y-0.5">{links.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-${label.toLowerCase().replace(' ', '-')}`} className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors', location === href || (href !== `/projects/${projectId}` && location.startsWith(href)) ? 'bg-primary/10 font-semibold text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><Icon size={16} />{label}</Link>)}</nav></div>}<div className="mt-auto space-y-1 border-t border-border pt-4"><Link href={projectId ? `/projects/${projectId}/settings` : '/settings'} data-testid="link-settings" className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"><Settings size={16} /> Settings</Link><Link href="/" data-testid="link-home" className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"><ArrowLeft size={16} /> Exit workspace</Link></div></aside>{open && <button aria-label="Close navigation" onClick={() => setOpen(false)} className="fixed inset-0 z-20 bg-foreground/20 lg:hidden" />}</>;
}

function AppHeader({ project }: { project?: Project }) {
  const { user } = useUserSafe(); const { signOut } = useClerkSafe();
  const initials = user ? `${user.firstName?.[0] ?? ''}${user.lastName?.[0] ?? ''}` || 'GT' : 'GT';
  const email = user?.primaryEmailAddress?.emailAddress ?? 'Growth team';
  return <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-md lg:pl-[294px] lg:pr-8"><div className="pl-10 lg:pl-0"><p className="font-mono-ui text-[9px] uppercase tracking-[.15em] text-muted-foreground">Workspace / {project?.name ?? 'Projects'}</p><h1 className="mt-1 font-display text-lg font-semibold tracking-[-.03em]">{project ? new URL(project.url).hostname : 'Projects overview'}</h1></div><div className="flex items-center gap-3"><span className="hidden items-center gap-2 rounded-full bg-primary/8 px-3 py-1.5 font-mono-ui text-[9px] uppercase tracking-[.1em] text-primary sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-primary" /> Workspace healthy</span><div className="group relative"><button data-testid="button-account-menu" className="flex items-center gap-2 rounded-lg p-1.5 transition-colors hover:bg-muted"><span className="grid h-8 w-8 place-items-center rounded-full bg-secondary font-mono-ui text-xs font-bold text-secondary-foreground">{initials}</span><ChevronDown size={14} className="text-muted-foreground" /></button><div className="invisible absolute right-0 top-12 w-48 translate-y-1 rounded-xl border border-border bg-card p-2 opacity-0 shadow-xl transition-all group-focus-within:visible group-focus-within:translate-y-0 group-focus-within:opacity-100"><p className="truncate px-3 py-2 text-xs text-muted-foreground">{email}</p>{signOut && <button onClick={() => signOut()} data-testid="button-sign-out" className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-muted-foreground hover:bg-muted hover:text-foreground"><LogOut size={14} /> Sign out</button>}</div></div></div></header>;
}

function useUserSafe() { try { return useUser(); } catch { return { user: undefined } as ReturnType<typeof useUser>; } }
function useClerkSafe() { try { return useClerk(); } catch { return { signOut: undefined } as Partial<ReturnType<typeof useClerk>>; } }

function AppShell({ children }: { children: React.ReactNode }) {
  const [location] = useLocation(); const projectId = getProjectId(location);
  const { data: project } = useGetProject(projectId, { query: { enabled: !!projectId, queryKey: getGetProjectQueryKey(projectId) } });
  return <div className="min-h-[100dvh] bg-background"><AppSidebar project={project} /><AppHeader project={project} /><main className="app-enter min-h-[calc(100dvh-72px)] px-5 py-8 lg:ml-[252px] lg:px-10 lg:py-10"><div className="mx-auto max-w-[1440px]">{children}</div></main></div>;
}

function PageIntro({ eyebrow, title, body, actions }: { eyebrow: string; title: string; body?: string; actions?: React.ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.16em] text-primary">{eyebrow}</p><h2 className="font-display mt-2 text-3xl font-semibold tracking-[-.06em] sm:text-4xl">{title}</h2>{body && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{body}</p>}</div>{actions && <div className="flex shrink-0 gap-2">{actions}</div>}</div>; }
function Button({ children, variant = 'primary', onClick, disabled, testId, type = 'button' }: { children: React.ReactNode; variant?: 'primary' | 'secondary' | 'quiet' | 'danger'; onClick?: () => void; disabled?: boolean; testId?: string; type?: 'button' | 'submit' }) { return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={cx('inline-flex items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold transition-all disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground shadow-sm hover:-translate-y-0.5 hover:shadow-md', variant === 'secondary' && 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-muted', variant === 'quiet' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'danger' && 'bg-destructive/10 text-destructive hover:bg-destructive/15')}>{children}</button>; }

function ProjectOverview() {
  const { data: projects, isLoading, isError, refetch } = useListProjects(); const [, setLocation] = useLocation();
  return <><PageIntro eyebrow="Portfolio" title="Your search surface" body="Keep every site, crawl, and prioritized fix in one clear view." actions={<Button testId="button-new-project" onClick={() => setLocation('/projects/new')}><Plus size={16} /> New project</Button>} />{isLoading ? <LoadingBlock label="Loading your projects" /> : isError ? <ErrorState onRetry={() => refetch()} /> : !projects?.length ? <EmptyState icon={Globe2} title="Start with a website" body="Create your first SEO project and run a crawl to see the health of your search surface." action={<Button onClick={() => setLocation('/projects/new')}><Plus size={16} /> Create project</Button>} /> : <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{projects.map(project => <ProjectCard key={project.id} project={project} />)}</div>}<div className="mt-12 border-t border-border pt-6"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Recent activity</p><div className="mt-4 grid gap-3 md:grid-cols-3"><Activity icon={RefreshCw} title="Crawl completed" body={projects?.[0] ? `${projects[0].name} is ready for review` : 'Your crawl events will appear here'} time={projects?.[0] ? fmtDate(projects[0].lastCrawlAt) : '—'} /><Activity icon={TriangleAlert} title="Issues waiting" body={projects?.[0] ? `${projects[0].issueCount} findings need triage` : 'No open findings yet'} time="Priority queue" /><Activity icon={Sparkles} title="Assistant ready" body="Ask grounded questions about any project" time="AI workspace" /></div></div></>;
}
function ProjectCard({ project }: { project: Project }) { const [, setLocation] = useLocation(); return <button onClick={() => setLocation(`/projects/${project.id}`)} data-testid={`card-project-${project.id}`} className="group rounded-xl border border-border bg-card p-6 text-left shadow-[0_2px_0_hsl(var(--border)/.45)] transition-all hover:-translate-y-1 hover:border-primary/35 hover:shadow-lg"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Globe2 size={19} /></span><div><h3 className="font-display font-semibold">{project.name}</h3><p className="mt-0.5 max-w-[180px] truncate text-xs text-muted-foreground">{project.url}</p></div></div><StatusBadge status={project.status} /></div><div className="mt-7 flex items-end justify-between"><div><p className="font-mono-ui text-[9px] uppercase tracking-[.12em] text-muted-foreground">Health score</p><p className="mt-1 font-display text-4xl font-semibold tracking-[-.07em]">{project.score}<span className="ml-1 text-sm font-medium text-muted-foreground">/100</span></p></div><div className="text-right"><p className="font-mono-ui text-[9px] uppercase tracking-[.12em] text-muted-foreground">Issues</p><p className="mt-1 font-display text-2xl font-semibold text-accent-foreground">{project.issueCount}</p></div></div><div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-xs text-muted-foreground"><span>{project.pagesCrawled} pages crawled</span><span className="text-primary opacity-0 transition-opacity group-hover:opacity-100">Open report <ArrowRight className="ml-1 inline" size={13} /></span></div></button>; }
function Activity({ icon: Icon, title, body, time }: { icon: typeof RefreshCw; title: string; body: string; time: string }) { return <div className="flex items-start gap-3 rounded-xl border border-border bg-card/50 p-4"><span className="mt-0.5 rounded-lg bg-muted p-2 text-primary"><Icon size={15} /></span><div className="min-w-0"><p className="text-sm font-semibold">{title}</p><p className="mt-1 truncate text-xs text-muted-foreground">{body}</p><p className="mt-3 font-mono-ui text-[9px] uppercase tracking-[.1em] text-muted-foreground">{time}</p></div></div>; }

function NewProject() {
  const [, setLocation] = useLocation(); const create = useCreateProject(); const [name, setName] = useState(''); const [url, setUrl] = useState(''); const [keywords, setKeywords] = useState(''); const [country, setCountry] = useState('United States'); const [language, setLanguage] = useState('English'); const params = new URLSearchParams(window.location.search);
  useEffect(() => { const preset = params.get('url'); if (preset && !url) setUrl(preset); }, []);
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { name, url: url.startsWith('http') ? url : `https://${url}`, keywords: keywords.split(',').map(x => x.trim()).filter(Boolean), country, language } }, { onSuccess: project => setLocation(`/projects/${project.id}`) }); };
  return <div className="mx-auto max-w-3xl"><Link href="/app" data-testid="link-back-projects" className="mb-8 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft size={15} /> All projects</Link><div className="rounded-2xl border border-border bg-card p-7 shadow-sm sm:p-10"><div className="flex items-start gap-4"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Globe2 size={23} /></span><div><p className="font-mono-ui text-[10px] uppercase tracking-[.16em] text-primary">New project</p><h2 className="font-display mt-2 text-3xl font-semibold tracking-[-.06em]">Bring a site into focus.</h2><p className="mt-2 text-sm text-muted-foreground">We’ll use these details to frame your first crawl and recommendations.</p></div></div><form onSubmit={submit} className="mt-9 space-y-6"><Field label="Project name" hint="A name your team will recognize"><input required value={name} onChange={e => setName(e.target.value)} data-testid="input-project-name" placeholder="Acme marketing site" className="field" /></Field><Field label="Website URL" hint="Include the canonical protocol"><input required type="url" value={url} onChange={e => setUrl(e.target.value)} data-testid="input-project-url" placeholder="https://example.com" className="field" /></Field><Field label="Target keywords" hint="Separate terms with commas"><input value={keywords} onChange={e => setKeywords(e.target.value)} data-testid="input-project-keywords" placeholder="technical SEO, site audit, growth marketing" className="field" /></Field><div className="grid gap-5 sm:grid-cols-2"><Field label="Country"><select value={country} onChange={e => setCountry(e.target.value)} data-testid="select-project-country" className="field"><option>United States</option><option>United Kingdom</option><option>Canada</option><option>Australia</option><option>Germany</option></select></Field><Field label="Language"><select value={language} onChange={e => setLanguage(e.target.value)} data-testid="select-project-language" className="field"><option>English</option><option>German</option><option>French</option><option>Spanish</option></select></Field></div><div className="flex items-center justify-between border-t border-border pt-6"><p className="text-xs text-destructive">{create.isError ? 'Could not create project. Check the URL and try again.' : ''}</p><Button type="submit" disabled={create.isPending} testId="button-create-project">{create.isPending ? <><Loader2 className="animate-spin" size={16} /> Creating…</> : <>Create project <ArrowRight size={16} /></>}</Button></div></form></div></div>;
}
function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) { return <label className="block"><span className="flex items-baseline justify-between text-sm font-semibold">{label}{hint && <span className="text-xs font-normal text-muted-foreground">{hint}</span>}</span><div className="mt-2">{children}</div></label>; }

function DashboardPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const { data, isLoading, isError, refetch } = useGetProjectDashboard(projectId, { query: { queryKey: getGetProjectDashboardQueryKey(projectId) } });
  if (isLoading) return <LoadingBlock label="Compiling audit evidence" />; if (isError || !data) return <ErrorState onRetry={() => refetch()} />;
  const { project, metrics } = data;
  const summaryItems: Array<[string, number, LucideIcon]> = [['Pages crawled',metrics.pages,FileCode2],['Critical issues',metrics.critical,TriangleAlert],['Broken links',metrics.brokenLinks,Link2],['Missing metadata',metrics.missingMetadata,Target]];
  return <><PageIntro eyebrow="Project overview" title="The signal behind the score" body={`Last crawled ${fmtTime(project.lastCrawlAt)}. Here’s where your technical health stands today.`} actions={<StartCrawlButton projectId={projectId} />} /><div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><div className="rounded-2xl border border-border bg-card p-7"><div className="flex flex-col justify-between gap-6 sm:flex-row sm:items-center"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Overall health</p><div className="mt-3 flex items-baseline gap-3"><span className="font-display text-6xl font-semibold tracking-[-.09em]">{project.score}</span><span className="font-mono-ui text-xs text-muted-foreground">/ 100</span></div><p className="mt-2 flex items-center gap-2 text-sm text-primary"><span className="rounded-full bg-primary/10 px-2 py-0.5">+4.8</span> since previous crawl</p></div><ScoreRing score={project.score} size={152} /></div><div className="mt-8 border-t border-border pt-5"><div className="flex items-center justify-between"><p className="font-mono-ui text-[10px] uppercase tracking-[.12em] text-muted-foreground">Score history</p><span className="text-xs text-muted-foreground">Last 7 crawls</span></div><div className="mt-4 h-20"><Sparkline points={data.scoreHistory} /></div></div></div><div className="rounded-2xl border border-border bg-card p-7"><div className="flex items-center justify-between"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Severity map</p><h3 className="mt-2 font-display text-xl font-semibold">Open issues</h3></div><Link href={`/projects/${projectId}/issues`} data-testid="link-view-issues" className="text-xs font-semibold text-primary hover:underline">View queue <ArrowRight className="ml-1 inline" size={13} /></Link></div><div className="mt-7 space-y-4">{(data.severityCounts.length ? data.severityCounts : [{label:'Critical',count:metrics.critical},{label:'High',count:metrics.high},{label:'Medium',count:metrics.medium},{label:'Low',count:metrics.low}]).map(item => <div key={item.label} className="flex items-center gap-3"><span className={cx('h-2 w-2 rounded-full', item.label.toLowerCase() === 'critical' ? 'bg-red-500' : item.label.toLowerCase() === 'high' ? 'bg-orange-400' : item.label.toLowerCase() === 'medium' ? 'bg-yellow-400' : 'bg-slate-400')} /><span className="flex-1 text-sm">{item.label}</span><span className="font-mono-ui text-sm">{item.count}</span><div className="h-1.5 w-24 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, item.count / Math.max(1, project.issueCount) * 100)}%` }} /></div></div>)}</div></div></div><div className="mt-5 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">{summaryItems.map(([label,value,Icon]) => <div key={label} className="rounded-xl border border-border bg-card p-5"><span className="grid h-8 w-8 place-items-center rounded-lg bg-muted text-primary"><Icon size={15} /></span><p className="mt-5 font-mono-ui text-[9px] uppercase tracking-[.12em] text-muted-foreground">{label}</p><p className="mt-1 font-display text-3xl font-semibold tracking-[-.06em]">{value}</p></div>)}</div><div className="mt-8"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Category performance</p><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{data.categoryScores.map(category => <div key={category.category} className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><span className="text-sm font-medium">{category.category}</span><span className="font-mono-ui text-xs text-primary">{category.score}</span></div><div className="mt-4 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${category.score}%` }} /></div></div>)}</div></div></>;
}
function StartCrawlButton({ projectId }: { projectId: string }) { const start = useStartCrawl(); const qc = useQueryClient(); return <Button disabled={start.isPending} onClick={() => start.mutate({ projectId, data: { maxPages: 100 } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListCrawlsQueryKey(projectId) }); qc.invalidateQueries({ queryKey: getGetProjectDashboardQueryKey(projectId) }); } })} testId="button-start-crawl">{start.isPending ? <Loader2 className="animate-spin" size={15} /> : <Play size={15} />} Run crawl</Button>; }

function PagesPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const { data, isLoading, isError, refetch } = useListPages(projectId, { query: { queryKey: getListPagesQueryKey(projectId) } }); const [search, setSearch] = useState(''); const [sort, setSort] = useState<'score' | 'issues'>('issues');
  const pages = useMemo(() => (data?.items ?? []).filter(p => p.url.toLowerCase().includes(search.toLowerCase()) || p.title?.toLowerCase().includes(search.toLowerCase())).sort((a,b) => sort === 'issues' ? b.issueCount - a.issueCount : a.score - b.score), [data, search, sort]);
  return <><PageIntro eyebrow="Pages explorer" title="Every URL, in context." body={data ? `${data.total} pages in the latest crawl. Search by URL or title, then open a page for its full report.` : undefined} actions={<Button variant="secondary" onClick={() => setSearch('')} testId="button-reset-page-search"><RefreshCw size={15} /> Refresh view</Button>} /><div className="rounded-2xl border border-border bg-card"><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} data-testid="input-page-search" placeholder="Search URLs or page titles…" className="field pl-9" /></div><label className="flex items-center gap-2 rounded-lg border border-input px-3 text-xs text-muted-foreground"><SlidersHorizontal size={14} /><select value={sort} onChange={e => setSort(e.target.value as 'score'|'issues')} data-testid="select-page-sort" className="bg-transparent py-2.5 text-foreground outline-none"><option value="issues">Most issues</option><option value="score">Lowest score</option></select></label></div>{isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-12" /><Skeleton className="h-12" /><Skeleton className="h-12" /></div> : isError ? <div className="p-5"><ErrorState onRetry={() => refetch()} /></div> : !pages.length ? <div className="p-5"><EmptyState title="No pages match" body="Try a different URL, title, or run a new crawl." /></div> : <div className="scrollbar-thin overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-muted/60 font-mono-ui text-[9px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3">Page</th><th className="px-5 py-3">Score</th><th className="px-5 py-3">Title</th><th className="px-5 py-3">Issues</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-border">{pages.map(page => <tr key={page.id} className="group transition-colors hover:bg-muted/40"><td className="max-w-[330px] px-5 py-4"><Link href={`/projects/${projectId}/pages/${page.id}`} data-testid={`link-page-${page.id}`} className="block truncate font-medium text-primary hover:underline">{page.url}</Link><span className="mt-1 block font-mono-ui text-[9px] uppercase text-muted-foreground">HTTP {page.status}</span></td><td className="px-5 py-4"><span className={cx('font-mono-ui text-sm', page.score >= 80 ? 'text-primary' : page.score >= 60 ? 'text-amber-700' : 'text-destructive')}>{page.score}</span></td><td className="max-w-[260px] truncate px-5 py-4 text-muted-foreground">{page.title || <span className="italic text-destructive">Missing title</span>}</td><td className="px-5 py-4"><span className={cx('rounded-full px-2 py-1 font-mono-ui text-[10px]', page.issueCount ? 'bg-accent/20 text-amber-800' : 'bg-primary/10 text-primary')}>{page.issueCount}</span></td><td className="px-5 py-4 text-right"><ArrowRight size={15} className="text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" /></td></tr>)}</tbody></table></div>}</div></>;
}

function PageReportPage() {
  const { projectId = '', pageId = '' } = useParams<{ projectId: string; pageId: string }>(); const { data, isLoading, isError, refetch } = useGetPage(projectId, pageId, { query: { queryKey: getGetPageQueryKey(projectId, pageId) } }); const report = data as PageReport | undefined;
  if (isLoading) return <LoadingBlock label="Inspecting page signals" />; if (isError || !report) return <ErrorState onRetry={() => refetch()} />;
  const blocks = [['Headings', `${report.headings.h1?.length ?? 0} H1 · ${report.headings.h2?.length ?? 0} H2`, FileCode2], ['Images', `${report.images.total ?? 0} total · ${report.images.missingAlt ?? 0} missing alt`, Target], ['Links', `${report.links.internal ?? 0} internal · ${report.links.broken ?? 0} broken`, Link2], ['Structured data', report.structuredData.present ? 'Detected' : 'Not detected', Code2]] as const;
  return <><Link href={`/projects/${projectId}/pages`} data-testid="link-back-pages" className="mb-7 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft size={15} /> Pages explorer</Link><PageIntro eyebrow="Page report" title={report.title || 'Untitled page'} body={report.url} actions={<span className="inline-flex items-center gap-2 rounded-lg bg-primary/10 px-3 py-2 text-xs font-semibold text-primary"><ShieldCheck size={14} /> {report.score}/100 health</span>} /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl border border-border bg-card p-7"><div className="flex items-center justify-between"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">On-page signals</p><h3 className="mt-2 font-display text-xl font-semibold">What the crawler saw</h3></div><ScoreRing score={report.score} size={94} label="score" /></div><div className="mt-8 grid gap-3 sm:grid-cols-2">{blocks.map(([label,value,Icon]) => <div key={label} className="rounded-xl border border-border bg-muted/35 p-4"><Icon size={17} className="text-primary" /><p className="mt-5 font-mono-ui text-[9px] uppercase tracking-[.1em] text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>)}</div><div className="mt-5 space-y-4 border-t border-border pt-5"><Signal label="Title" value={report.title} /><Signal label="H1" value={report.h1} /><Signal label="Meta description" value={report.metaDescription} /></div></div><div className="rounded-2xl border border-border bg-card p-7"><div className="flex items-center justify-between"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Issues on this page</p><h3 className="mt-2 font-display text-xl font-semibold">{report.issues.length} findings</h3></div><TriangleAlert size={20} className="text-accent-foreground" /></div><div className="mt-6 space-y-3">{report.issues.length ? report.issues.map(issue => <IssueItem key={issue.id} issue={issue} projectId={projectId} />) : <EmptyState icon={CheckCircle2} title="Clean page" body="No issues were found on this URL in the latest crawl." />}</div></div></div></>;
}
function Signal({ label, value }: { label: string; value?: string | null }) { return <div><p className="font-mono-ui text-[9px] uppercase tracking-[.1em] text-muted-foreground">{label}</p><p className={cx('mt-2 text-sm leading-6', !value && 'italic text-destructive')}>{value || `Missing ${label.toLowerCase()}`}</p></div>; }

function IssuesPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const { data: issues, isLoading, isError, refetch } = useListIssues(projectId, { query: { queryKey: getListIssuesQueryKey(projectId) } }); const [severity, setSeverity] = useState('all'); const [reviewed, setReviewed] = useState('open'); const [search, setSearch] = useState('');
  const filtered = useMemo(() => (issues ?? []).filter(i => (severity === 'all' || i.severity === severity) && (reviewed === 'all' || (reviewed === 'open' ? !i.reviewed : i.reviewed)) && (`${i.title} ${i.url} ${i.category}`.toLowerCase().includes(search.toLowerCase()))), [issues, severity, reviewed, search]);
  return <><PageIntro eyebrow="Issue management" title="A queue worth clearing." body={`${issues?.length ?? 0} findings across the latest crawl. Review them as a team, then move from evidence to implementation.`} actions={<Button variant="secondary" testId="button-filter-issues" onClick={() => { setSeverity('all'); setReviewed('open'); setSearch(''); }}><Filter size={15} /> Reset filters</Button>} /><div className="grid gap-5 lg:grid-cols-[230px_1fr]"><div className="space-y-5"><div className="rounded-xl border border-border bg-card p-4"><p className="font-mono-ui text-[9px] uppercase tracking-[.14em] text-muted-foreground">Status</p><div className="mt-3 space-y-1">{[['open','Open'],['reviewed','Reviewed'],['all','All issues']].map(([value,label]) => <button key={value} onClick={() => setReviewed(value)} data-testid={`button-filter-${value}`} className={cx('flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm', reviewed === value ? 'bg-primary/10 font-semibold text-primary' : 'text-muted-foreground hover:bg-muted')}>{label}<span className="font-mono-ui text-[10px]">{value === 'open' ? issues?.filter(i=>!i.reviewed).length : value === 'reviewed' ? issues?.filter(i=>i.reviewed).length : issues?.length}</span></button>)}</div></div><div className="rounded-xl border border-border bg-card p-4"><p className="font-mono-ui text-[9px] uppercase tracking-[.14em] text-muted-foreground">Severity</p><div className="mt-3 flex flex-wrap gap-2 lg:block">{['all','Critical','High','Medium','Low'].map(value => <button key={value} onClick={() => setSeverity(value)} data-testid={`button-severity-${value.toLowerCase()}`} className={cx('mr-1 rounded-full px-3 py-1.5 text-xs lg:mb-2 lg:block', severity === value ? 'bg-foreground text-background' : 'bg-muted text-muted-foreground hover:text-foreground')}>{value}</button>)}</div></div></div><div className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-4"><div className="relative"><Search className="absolute left-3 top-2.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} data-testid="input-issue-search" placeholder="Search issues, categories, URLs…" className="field pl-9" /></div></div>{isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-28" /><Skeleton className="h-28" /></div> : isError ? <div className="p-5"><ErrorState onRetry={() => refetch()} /></div> : !filtered.length ? <div className="p-5"><EmptyState icon={CheckCircle2} title="Nothing in this queue" body="Your filters are clear. That is a good place to be." /></div> : <div className="divide-y divide-border">{filtered.map(issue => <IssueItem key={issue.id} issue={issue} projectId={projectId} expanded />)}</div>}</div></div></>;
}
function IssueItem({ issue, projectId, expanded = false }: { issue: SEOIssue; projectId: string; expanded?: boolean }) { const update = useUpdateIssue(); const qc = useQueryClient(); const [open, setOpen] = useState(false); const shown = expanded || open; const colors: Record<string,string> = { Critical:'bg-red-100 text-red-700', High:'bg-orange-100 text-orange-700', Medium:'bg-yellow-100 text-yellow-700', Low:'bg-slate-100 text-slate-600' }; return <div className="p-5"><div className="flex items-start gap-3"><span className={cx('mt-0.5 rounded-full px-2 py-1 font-mono-ui text-[9px] uppercase', colors[issue.severity])}>{issue.severity}</span><div className="min-w-0 flex-1"><button onClick={() => setOpen(!open)} data-testid={`button-toggle-issue-${issue.id}`} className="text-left font-semibold hover:text-primary">{issue.title}</button><p className="mt-1 truncate text-xs text-muted-foreground">{issue.url} · {issue.category}</p></div><button onClick={() => update.mutate({ projectId, issueId: issue.id, data: { reviewed: !issue.reviewed } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListIssuesQueryKey(projectId) }) })} disabled={update.isPending} data-testid={`button-review-issue-${issue.id}`} className={cx('shrink-0 rounded-lg border px-3 py-1.5 text-xs font-semibold transition-colors', issue.reviewed ? 'border-primary/20 bg-primary/10 text-primary' : 'border-border text-muted-foreground hover:border-primary/30 hover:text-primary')}>{issue.reviewed ? <><Check size={13} className="mr-1 inline" /> Reviewed</> : 'Mark reviewed'}</button></div>{shown && <div className="ml-0 mt-5 grid gap-4 border-t border-border pt-5 text-sm sm:grid-cols-3"><div><p className="label">Description</p><p className="mt-2 leading-6 text-muted-foreground">{issue.description}</p></div><div><p className="label">Why it matters</p><p className="mt-2 leading-6 text-muted-foreground">{issue.whyItMatters}</p></div><div><p className="label text-primary">Recommended fix</p><p className="mt-2 leading-6 text-foreground">{issue.recommendedFix}</p></div></div>}</div>; }

function CrawlsPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const { data: crawls, isLoading, isError, refetch } = useListCrawls(projectId, { query: { queryKey: getListCrawlsQueryKey(projectId) } }); const [selected, setSelected] = useState<string | null>(null); const start = useStartCrawl(); const qc = useQueryClient(); const active = crawls?.find(c => c.id === selected);
  const startIt = () => start.mutate({ projectId, data: { maxPages: 100 } }, { onSuccess: crawl => { setSelected(crawl.id); qc.invalidateQueries({ queryKey: getListCrawlsQueryKey(projectId) }); } });
  return <><PageIntro eyebrow="Crawl history" title="See the work behind the score." body="Each crawl is an evidence snapshot. Re-run when you ship meaningful changes." actions={<Button onClick={startIt} disabled={start.isPending} testId="button-start-crawl-history">{start.isPending ? <Loader2 className="animate-spin" size={15} /> : <Play size={15} />} Start new crawl</Button>} />{active && <CrawlProgress projectId={projectId} crawl={active} />}<div className="rounded-2xl border border-border bg-card">{isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-16" /><Skeleton className="h-16" /></div> : isError ? <div className="p-5"><ErrorState onRetry={() => refetch()} /></div> : !crawls?.length ? <div className="p-5"><EmptyState icon={History} title="No crawls yet" body="Start a crawl to create your first evidence snapshot." action={<Button onClick={startIt}><Play size={15} /> Start crawl</Button>} /></div> : <div className="divide-y divide-border">{crawls.map(crawl => <button key={crawl.id} onClick={() => setSelected(crawl.id)} data-testid={`button-crawl-${crawl.id}`} className={cx('flex w-full items-center gap-4 p-5 text-left transition-colors hover:bg-muted/40', selected === crawl.id && 'bg-primary/5')}><span className="grid h-9 w-9 place-items-center rounded-lg bg-muted text-primary"><History size={16} /></span><div className="min-w-0 flex-1"><div className="flex items-center gap-3"><span className="font-semibold">{fmtDate(crawl.startedAt)}</span><StatusBadge status={crawl.status} /></div><p className="mt-1 text-xs text-muted-foreground">{crawl.pagesAnalyzed} pages analyzed · {crawl.issuesFound} issues found</p></div><div className="text-right"><p className="font-display text-xl font-semibold">{crawl.score ?? '—'}</p><p className="font-mono-ui text-[9px] uppercase tracking-[.1em] text-muted-foreground">score</p></div><ArrowRight size={15} className="text-muted-foreground" /></button>)}</div>}</div></>;
}
function CrawlProgress({ projectId, crawl }: { projectId: string; crawl: Crawl }) { const { data } = useGetCrawl(projectId, crawl.id, { query: { enabled: crawl.status === 'queued' || crawl.status === 'crawling', refetchInterval: 2500, queryKey: getGetCrawlQueryKey(projectId, crawl.id) } }); const current = data ?? crawl; const progress = current.pagesDiscovered ? Math.round(current.pagesAnalyzed / current.pagesDiscovered * 100) : 8; return <div className="mb-5 overflow-hidden rounded-2xl border border-primary/20 bg-primary/5 p-6"><div className="flex items-start justify-between"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-primary">Live crawl</p><h3 className="mt-2 font-display text-xl font-semibold">{current.status === 'completed' ? 'Crawl complete' : current.status === 'failed' ? 'Crawl stopped' : 'Crawling your site'}</h3><p className="mt-1 text-sm text-muted-foreground">{current.pagesAnalyzed} of {current.pagesDiscovered || '…'} pages analyzed</p></div><span className="font-display text-3xl font-semibold text-primary">{current.status === 'completed' ? 100 : progress}%</span></div><div className="relative mt-6 h-2 overflow-hidden rounded-full bg-primary/10"><div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${current.status === 'completed' ? 100 : progress}%` }} />{current.status === 'crawling' && <div className="scan-line absolute inset-y-0 left-0 w-1/3 bg-white/40" />}</div>{current.error && <p className="mt-3 text-xs text-destructive">{current.error}</p>}</div>; }

function AssistantPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const ask = useAskAssistant(); const { data: recommendations } = useListRecommendations(projectId, { query: { queryKey: getListRecommendationsQueryKey(projectId) } }); const [question, setQuestion] = useState(''); const [answer, setAnswer] = useState<{ answer: string; sources: Array<{ label: string; url: string }> } | null>(null);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!question.trim()) return; ask.mutate({ projectId, data: { question } }, { onSuccess: result => { setAnswer(result); setQuestion(''); } }); };
  return <><PageIntro eyebrow="Grounded assistant" title="Ask the crawl, not the void." body="SEOlytic answers from this project’s evidence so your next decision has a paper trail." /><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><div className="rounded-2xl border border-border bg-card"><div className="border-b border-border bg-[#17323a] p-7 text-slate-100"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-teal-300/15 text-teal-300"><Bot size={20} /></span><div><h3 className="font-display text-xl font-semibold">SEOlytic assistant</h3><p className="mt-1 text-xs text-slate-400">Grounded in your latest crawl</p></div></div></div><div className="min-h-[300px] p-7">{answer ? <div className="app-enter"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-primary">Answer</p><div className="prose prose-sm mt-4 max-w-none text-foreground"><p className="whitespace-pre-wrap leading-7">{answer.answer}</p></div>{answer.sources?.length > 0 && <div className="mt-7 border-t border-border pt-5"><p className="label">Sources</p><div className="mt-3 space-y-2">{answer.sources.map(source => <a key={source.url} href={source.url} target="_blank" rel="noreferrer" data-testid="link-assistant-source" className="flex items-center gap-2 text-xs text-primary hover:underline"><ExternalLink size={12} />{source.label}</a>)}</div></div>}</div> : <div className="flex min-h-[270px] flex-col items-center justify-center text-center"><Sparkles className="mb-4 text-accent" size={27} /><h3 className="font-display text-xl font-semibold">What do you want to know?</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Try “Which issues are blocking our most valuable pages?” or “What should engineering fix first?”</p></div>}</div><form onSubmit={submit} className="border-t border-border p-4"><div className="flex items-end gap-2 rounded-xl border border-input bg-muted/40 p-2 focus-within:border-primary/50"><textarea value={question} onChange={e => setQuestion(e.target.value)} data-testid="textarea-assistant-question" placeholder="Ask about this project…" rows={2} className="min-h-[52px] flex-1 resize-none bg-transparent px-2 py-1 text-sm outline-none placeholder:text-muted-foreground" /><button type="submit" disabled={!question.trim() || ask.isPending} data-testid="button-ask-assistant" className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-50">{ask.isPending ? <Loader2 className="animate-spin" size={16} /> : <ArrowRight size={16} />}</button></div>{ask.isError && <p className="mt-2 text-xs text-destructive">The assistant could not answer right now. Try again.</p>}</form></div><div className="rounded-2xl border border-border bg-card p-7"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">AI recommendations</p><h3 className="mt-2 font-display text-xl font-semibold">Recent guidance</h3><div className="mt-6 space-y-4">{recommendations?.length ? recommendations.slice(0,5).map(rec => <div key={rec.id} className="border-l-2 border-accent pl-4"><p className="text-sm font-semibold">{rec.problem}</p><p className="mt-1 line-clamp-3 text-xs leading-5 text-muted-foreground">{rec.recommendedSolution}</p></div>) : <EmptyState icon={Sparkles} title="No recommendations yet" body="Ask the assistant a question to start a project-specific thread." />}</div></div></div></>;
}

function SettingsPage() {
  const { projectId = '' } = useParams<{ projectId: string }>(); const { data: project, isLoading, refetch } = useGetProject(projectId, { query: { queryKey: getGetProjectQueryKey(projectId) } }); const update = useUpdateProject(); const remove = useDeleteProject(); const [, setLocation] = useLocation(); const [name, setName] = useState(''); const [keywords, setKeywords] = useState('');
  useEffect(() => { if (project) { setName(project.name); setKeywords(project.keywords?.join(', ') ?? ''); } }, [project?.id]);
  if (isLoading || !project) return <LoadingBlock label="Loading project settings" />;
  const save = (e: React.FormEvent) => { e.preventDefault(); update.mutate({ projectId, data: { name, keywords: keywords.split(',').map(k => k.trim()).filter(Boolean) } }, { onSuccess: () => refetch() }); };
  return <><PageIntro eyebrow="Project settings" title="Keep the brief current." body="These details shape how your team reads this project." /><div className="grid gap-5 lg:grid-cols-[1fr_320px]"><form onSubmit={save} className="rounded-2xl border border-border bg-card p-7"><h3 className="font-display text-xl font-semibold">Project profile</h3><div className="mt-7 space-y-6"><Field label="Project name"><input value={name} onChange={e => setName(e.target.value)} data-testid="input-settings-name" className="field" /></Field><Field label="Website URL"><input value={project.url} disabled data-testid="input-settings-url" className="field opacity-70" /></Field><Field label="Target keywords"><input value={keywords} onChange={e => setKeywords(e.target.value)} data-testid="input-settings-keywords" className="field" /></Field></div><div className="mt-7 flex justify-end border-t border-border pt-5"><Button type="submit" disabled={update.isPending} testId="button-save-settings">{update.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Save changes</Button></div></form><div className="rounded-2xl border border-destructive/20 bg-destructive/5 p-7"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-destructive">Danger zone</p><h3 className="mt-2 font-display text-xl font-semibold">Delete project</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">Remove this project and its crawl history. This cannot be undone.</p><Button variant="danger" onClick={() => { if (window.confirm('Delete this project?')) remove.mutate({ projectId }, { onSuccess: () => setLocation('/app') }); }} testId="button-delete-project"><Trash2 size={15} /> Delete project</Button></div></div></>;
}

function AccountSettings() {
  const { data: projects, isLoading } = useListProjects(); const { user } = useUserSafe(); const { signOut } = useClerkSafe(); const update = useUpdateProject(); const qc = useQueryClient(); const [selected, setSelected] = useState(''); const project = projects?.find(item => item.id === selected) ?? projects?.[0]; const [name, setName] = useState('');
  useEffect(() => { if (project) { setSelected(project.id); setName(project.name); } }, [project?.id]);
  const save = (e: React.FormEvent) => { e.preventDefault(); if (!project) return; update.mutate({ projectId: project.id, data: { name } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListProjectsQueryKey() }) }); };
  return <><PageIntro eyebrow="Workspace settings" title="A workspace that stays yours." body="Manage your account and the project brief your team sees." /><div className="grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><section className="rounded-2xl border border-border bg-card p-7"><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Account</p><div className="mt-5 flex items-center gap-4"><span className="grid h-12 w-12 place-items-center rounded-full bg-secondary font-display text-lg font-semibold text-secondary-foreground">{user ? `${user.firstName?.[0] ?? ''}${user.lastName?.[0] ?? ''}` : 'GT'}</span><div><h3 className="font-display text-lg font-semibold">{user?.fullName ?? 'Growth team'}</h3><p className="text-sm text-muted-foreground">{user?.primaryEmailAddress?.emailAddress ?? 'Workspace account'}</p></div></div><div className="mt-7 border-t border-border pt-5"><Button variant="secondary" onClick={() => signOut?.()} testId="button-settings-sign-out"><LogOut size={15} /> Sign out</Button></div></section><section className="rounded-2xl border border-border bg-card p-7"><div className="flex items-start justify-between gap-4"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">Project preferences</p><h3 className="mt-2 font-display text-xl font-semibold">The working brief</h3></div><Settings className="text-primary" size={20} /></div>{isLoading ? <div className="mt-7 space-y-3"><Skeleton className="h-11" /><Skeleton className="h-11" /></div> : !projects?.length ? <div className="mt-7"><EmptyState icon={Globe2} title="No project to configure" body="Create a project first, then tune its brief here." /></div> : <form onSubmit={save} className="mt-7 space-y-5"><Field label="Project"><select value={selected} onChange={e => { setSelected(e.target.value); const next = projects.find(item => item.id === e.target.value); setName(next?.name ?? ''); }} data-testid="select-settings-project" className="field">{projects.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Project name"><input value={name} onChange={e => setName(e.target.value)} data-testid="input-account-project-name" className="field" /></Field><div className="flex items-center justify-between border-t border-border pt-5"><Link href={project ? `/projects/${project.id}/settings` : '/app'} data-testid="link-advanced-project-settings" className="text-xs font-semibold text-primary hover:underline">Advanced project settings <ArrowRight className="ml-1 inline" size={13} /></Link><Button type="submit" disabled={update.isPending} testId="button-save-account-settings">{update.isPending ? <Loader2 className="animate-spin" size={15} /> : <Check size={15} />} Save</Button></div></form>}</section></div></>;
}

function AuthFallback({ kind }: { kind: 'sign-in' | 'sign-up' }) { const [, setLocation] = useLocation(); return <main className="noise grid min-h-[100dvh] place-items-center bg-[#13252d] px-5"><div className="w-full max-w-[420px] rounded-2xl border border-white/15 bg-[#1b333b] p-7 text-slate-100 shadow-2xl"><Logo dark /><div className="mt-12"><p className="font-mono-ui text-[10px] uppercase tracking-[.16em] text-teal-300">SEOlytic workspace</p><h1 className="font-display mt-3 text-3xl font-semibold tracking-[-.06em]">{kind === 'sign-in' ? 'Welcome back.' : 'Start with the signal.'}</h1><p className="mt-2 text-sm text-slate-400">{kind === 'sign-in' ? 'Sign in to return to your audit workspace.' : 'Create an account to run your first technical audit.'}</p><div className="mt-8 space-y-4"><input data-testid="input-auth-email" placeholder="Work email" className="field border-white/15 bg-white/[.06] text-white placeholder:text-slate-500" /><input data-testid="input-auth-password" type="password" placeholder="Password" className="field border-white/15 bg-white/[.06] text-white placeholder:text-slate-500" /><Button onClick={() => setLocation('/app')} testId="button-auth-submit">{kind === 'sign-in' ? 'Sign in' : 'Create account'} <ArrowRight size={15} /></Button></div><p className="mt-6 text-center text-xs text-slate-400">{kind === 'sign-in' ? 'New here? ' : 'Already have an account? '}<button onClick={() => setLocation(kind === 'sign-in' ? '/sign-up' : '/sign-in')} data-testid="button-switch-auth" className="text-teal-300 hover:underline">{kind === 'sign-in' ? 'Create an account' : 'Sign in'}</button></p></div></div></main>; }

function SignInPage() { return <main className="grid min-h-[100dvh] place-items-center bg-background px-4"><SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} appearance={clerkAppearance} /></main>; }
function SignUpPage() { return <main className="grid min-h-[100dvh] place-items-center bg-background px-4"><SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} appearance={clerkAppearance} /></main>; }
const clerkAppearance = { theme: shadcn, variables: { colorPrimary: 'hsl(169 65% 33%)', colorBackground: 'hsl(45 38% 99%)', colorForeground: 'hsl(218 31% 16%)', colorMutedForeground: 'hsl(216 16% 46%)', fontFamily: 'DM Sans, sans-serif', borderRadius: '0.8rem' }, elements: { cardBox: 'bg-card border border-border shadow-xl rounded-2xl', headerTitle: 'font-display', formButtonPrimary: 'bg-primary hover:bg-primary/90', footerActionLink: 'text-primary', formFieldInput: 'bg-background border-input' } };

function ProtectedPage({ children }: { children: React.ReactNode }) { const { isLoaded, isSignedIn } = useAuth(); if (!isLoaded) return <div className="grid min-h-[100dvh] place-items-center bg-background"><Loader2 className="animate-spin text-primary" /></div>; return isSignedIn ? <>{children}</> : <Redirect to="/sign-in" />; }
function OpenPage({ children }: { children: React.ReactNode }) { return <>{children}</>; }
function ClerkHome() { const { isLoaded, isSignedIn } = useAuth(); if (!isLoaded) return <div className="grid min-h-[100dvh] place-items-center bg-[#13252d]"><Loader2 className="animate-spin text-teal-300" /></div>; return isSignedIn ? <Redirect to="/app" /> : <Landing />; }
function AppRoutes({ clerk }: { clerk: boolean }) { const Guard = clerk ? ProtectedPage : OpenPage; const routes = <Switch><Route path="/" component={clerk ? ClerkHome : Landing} /><Route path="/sign-in/*?" component={() => clerk ? <SignInPage /> : <AuthFallback kind="sign-in" />} /><Route path="/sign-up/*?" component={() => clerk ? <SignUpPage /> : <AuthFallback kind="sign-up" />} /><Route path="/projects/new" component={() => <Guard><AppShell><NewProject /></AppShell></Guard>} /><Route path="/projects/:projectId/pages/:pageId" component={() => <Guard><AppShell><PageReportPage /></AppShell></Guard>} /><Route path="/projects/:projectId/pages" component={() => <Guard><AppShell><PagesPage /></AppShell></Guard>} /><Route path="/projects/:projectId/issues" component={() => <Guard><AppShell><IssuesPage /></AppShell></Guard>} /><Route path="/projects/:projectId/crawls" component={() => <Guard><AppShell><CrawlsPage /></AppShell></Guard>} /><Route path="/projects/:projectId/assistant" component={() => <Guard><AppShell><AssistantPage /></AppShell></Guard>} /><Route path="/projects/:projectId/settings" component={() => <Guard><AppShell><SettingsPage /></AppShell></Guard>} /><Route path="/projects/:projectId" component={() => <Guard><AppShell><DashboardPage /></AppShell></Guard>} /><Route path="/settings" component={() => <Guard><AppShell><AccountSettings /></AppShell></Guard>} /><Route path="/app" component={() => <Guard><AppShell><ProjectOverview /></AppShell></Guard>} /><Route component={() => <div className="p-10">Page not found</div>} /></Switch>; return routes; }

function ClerkApp() { return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={{ ...clerkAppearance, options: { logoImageUrl: `${window.location.origin}${basePath}/logo.svg`, logoLinkUrl: basePath || '/' } }} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`}><QueryClientProvider client={queryClient}><AppRoutes clerk /></QueryClientProvider></ClerkProvider>; }
function DemoApp() { return <QueryClientProvider client={queryClient}><AppRoutes clerk={false} /></QueryClientProvider>; }
function App() { return <TooltipProvider><ErrorBoundary><WouterRouter base={basePath}><Toaster />{clerkPubKey ? <ClerkApp /> : <DemoApp />}</WouterRouter></ErrorBoundary></TooltipProvider>; }
export default App;